export interface UserAttributes {
	id: number;
	createdAt: string;
	updatedAt: string;
}

export type UserCreateInput = Omit<UserAttributes, 'id' | 'createdAt' | 'updatedAt'>;
export type UserUpdateInput = Partial<UserCreateInput>;

import type { PersistenceAdapter } from './adapters/types';
import type { UserAttributes, UserCreateInput, UserUpdateInput } from './User.types';

const tableName = 'users';

export class User {
	static find(adapter: PersistenceAdapter, id: number): Promise<UserAttributes | null> {
		return adapter.find(tableName, id);
	}

	static findBy(
		adapter: PersistenceAdapter,
		fields: Partial<UserAttributes>
	): Promise<UserAttributes[]> {
		return adapter.findBy(tableName, fields);
	}

	static create(adapter: PersistenceAdapter, input: UserCreateInput): Promise<UserAttributes> {
		return adapter.create(tableName, input);
	}

	static update(
		adapter: PersistenceAdapter,
		id: number,
		input: UserUpdateInput
	): Promise<UserAttributes | null> {
		return adapter.update(tableName, id, input);
	}

	static delete(adapter: PersistenceAdapter, id: number): Promise<boolean> {
		return adapter.delete(tableName, id);
	}
}

import type { PersistenceAdapter } from './types';

export function createPostgresAdapter(): PersistenceAdapter {
	return {
		find: async () => null,
		findBy: async () => [],
		create: async () => {
			throw new Error('Postgres create adapter is generated as a starting point.');
		},
		update: async () => null,
		delete: async () => false
	};
}

-- reversible: DROP TABLE IF EXISTS users;
CREATE TABLE IF NOT EXISTS users (
	id INTEGER PRIMARY KEY,
	created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

import { expect, test } from 'vitest';
import { User } from '../../src/models/User';

test('User exposes a small ActiveRecord-like API', () => {
	expect(User.find).toBeTypeOf('function');
	expect(User.create).toBeTypeOf('function');
	expect(User.update).toBeTypeOf('function');
	expect(User.delete).toBeTypeOf('function');
});

